/bin/zsh -lc ".venv/bin/python -c 'import json; from pathlib import Path; from readme_lab.evaluation import load_response, load_scorecard, score_review_response; root=Path(\"evals/runs/v0.2.0-rc.1\"); scenarios=Path(\"evals/scenarios\"); pairs=((\"finding\",\"missing-first-path\"),(\"no-finding\",\"adequate-first-path\"));
for run,scenario in pairs:
 response=root/run/\"response.json\"; score=root/run/\"score.json\"; capsule=scenarios/scenario/\"capsule.toml\"; load_response(response); load_scorecard(capsule); computed=score_review_response(capsule,response,events_path=root/run/\"events.jsonl\",stderr_path=root/run/\"stderr.log\"); stored=json.loads(score.read_text()); print(run, \"response_valid\", True, \"score_recomputed_equal\", computed==stored, \"result\", computed[\"result\"])'"

